const $ = (s, root = document) => root.querySelector(s);
const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => new Intl.NumberFormat('en-NL', {style:'currency',currency:'EUR',maximumFractionDigits:2}).format((cents || 0)/100);
const dateLabel = value => value ? new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value.slice(0,10)+'T12:00:00')) : '—';
const today = () => new Date().toLocaleDateString('en-CA');
const initials = name => (name || '?').split(' ').filter(Boolean).map(s=>s[0]).slice(0,2).join('').toUpperCase();
const state = {me:null,company:null,data:{},page:'overview',filter:'All',search:'',busy:false,overviewPeriod:null};
