function modal(title,body){
 const d=$('#modal');
 d.innerHTML=`<div class="modal-header"><h2 id="modal-title">${e(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;
 if(!d.open)d.showModal();
}
function closeModal(){$('#modal').close();}
function field(def){
 const [name,label,type='text',opts={}] = def;
 const value=opts.value??'';
 const required=opts.required===false?'':'required';
 const wide=opts.wide?'wide':'';
 if(type==='checkbox')return `<div class="field checkbox wide"><input type="checkbox" name="${name}" id="f-${name}" ${value?'checked':''} ${required}><label for="f-${name}">${e(label)}</label></div>`;
 let control;
 if(type==='select')control=`<select name="${name}" id="f-${name}" ${required}>${opts.optional?'<option value="">Not linked</option>':''}${(opts.options||[]).map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(l)}</option>`;}).join('')}</select>`;
 else if(type==='textarea')control=`<textarea name="${name}" id="f-${name}" ${required} maxlength="5000">${e(value)}</textarea>`;
 else control=`<input type="${type}" name="${name}" id="f-${name}" value="${e(value)}" ${required} ${type==='number'?`step="${opts.step||'0.01'}" min="${opts.min??0}"`:''} ${type==='file'?'accept="application/pdf,image/png,image/jpeg"':''} ${opts.max?`max="${e(opts.max)}"`:''} ${opts.placeholder?`placeholder="${e(opts.placeholder)}"`:''} ${type==='password'?'minlength="12" autocomplete="new-password"':''}>`;
 return `<div class="field ${wide}"><label for="f-${name}">${e(label)}</label>${control}${opts.hint?`<small>${e(opts.hint)}</small>`:''}</div>`;
}
function formModal(title,fields,onSubmit,options={}){
 modal(title,`${options.intro?`<div class="modal-note">${options.intro}</div>`:''}<form id="record-form"><div class="form-grid">${fields.map(field).join('')}</div><div class="form-error" role="alert"></div><div class="modal-footer">${button('Cancel','close-modal')}<button class="button primary" type="submit">${e(options.submit||'Save record')}</button></div></form>`);
 $('#record-form').addEventListener('submit',async ev=>{
  ev.preventDefault();const form=ev.currentTarget;const submit=$('button[type="submit"]',form);submit.disabled=true;
  const fd=new FormData(form);const data=Object.fromEntries(fd);fields.filter(f=>f[2]==='checkbox').forEach(f=>data[f[0]]=fd.has(f[0]));
  try{await onSubmit(data,fd);if($('#record-form')===form)closeModal();await refresh();toast(options.success||'Saved to your workspace.');}
  catch(err){$('.form-error',form).textContent=err.message;submit.disabled=false;}
 });
}
