  if(action==='overview-period'){const current=(state.data.today||today()).slice(0,7);const selected=state.overviewPeriod||current;const next=shiftOverviewMonth(selected,Number(el.dataset.delta));state.overviewPeriod=next>current?current:next;render();}
  else if(action==='navigate'){closeModal();state.page=el.dataset.page;state.filter='All';history.replaceState(null,'','#'+state.page);render();window.scrollTo(0,0);if(state.page==='portal-inbox'||state.page==='tenant-messages'){const unread=rows('notifications').filter(n=>n.target===state.page&&!n.is_read);if(unread.length)Promise.all(unread.map(n=>api(`/api/notifications/${n.id}/read`,{method:'POST'}))).then(()=>refresh()).catch(()=>toast('Inbox opened, but some notifications could not be marked read. Check the connection and refresh.'));}}
 else if(action==='service-group-form')createServiceGroupForm();
