document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(el){if(el.matches('select[data-action="role-change"]'))return;ev.preventDefault();safe(()=>handleAction(el));}});
document.addEventListener('change',ev=>{const el=ev.target.closest('select[data-action="role-change"]');if(!el)return;const target=el.value;if(target==='remove'&&!confirm('Remove this person’s access to the current company?')){refresh();return;}safe(async()=>{await api(`/api/staff/${el.dataset.user}/role`,{method:'POST',body:{company_id:state.company,role:target}});await refresh();toast('Team access updated.');});});
document.addEventListener('keydown',ev=>{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();$('#global-search')?.focus();}});
$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal')){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeModal();}});

function renderLogin(){
 $('#app').innerHTML=`<div class="login-page"><section class="login-story"><div class="brand"><span class="brand-mark">h</span><div>haven<small>PROPERTY MANAGEMENT</small></div></div><div><div class="eyebrow">A BETTER DAY AT THE OFFICE</div><h1>Good homes.<br>Clear records.<br>Peace of mind.</h1><p>A thoughtful workspace for your properties, your people and everything in between.</p>${houseArt()}</div><div class="login-story-footer">Built around the details that make a difference.</div></section><section class="login-form-side"><form class="login-form" id="login-form"><div class="eyebrow">YOUR WORKSPACE AWAITS</div><h2>Welcome back</h2><p>Sign in to see how your portfolio is doing.</p><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" required autocomplete="username" placeholder="you@company.nl"></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" required autocomplete="current-password" placeholder="Enter your password"></div><div class="form-error" role="alert"></div><button class="button primary" type="submit">Sign in to Haven ${icon('arrow')}</button><div class="login-small">Staff access only. Tenants can submit payment proof through the secure link provided with their invoice.</div></form></section></div>`;
 $('#login-form').addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.currentTarget;const btn=$('button',f);btn.disabled=true;try{const credentials=Object.fromEntries(new FormData(f));await api('/api/login',{method:'POST',body:credentials});const identity=await api('/api/me');if(identity.tenant_access){await api('/api/login',{method:'POST',body:credentials,headers:{'X-Haven-Portal':'tenant'}});location.href='/tenant';return;}if(identity.contractor_access){await api('/api/login',{method:'POST',body:credentials,headers:{'X-Haven-Portal':'contractor'}});location.href='/contractor';return;}await boot();}catch(err){$('.form-error',f).textContent=err.message;btn.disabled=false;}});
}
async function pollMessageBadge(){
 if(!state.me||!state.company)return;
 try{
  const notifications=await api('/api/notifications');
  const previous=rows('notifications');
  state.data.notifications=notifications.filter(n=>n.company_id===state.company);
  const fresh=state.data.notifications.filter(n=>!n.is_read&&!previous.some(old=>old.id===n.id)&&true);
  if(fresh.length){const newest=fresh[0];toast(`${newest.title}: ${newest.body}`);}
  const unreadFor=target=>state.data.notifications.filter(n=>n.target===target&&!n.is_read).length;
  const count=state.data.notifications.filter(n=>!n.is_read).length;
  for(const target of ['portal-inbox','tenant-messages']){
   const link=$(`[data-action="navigate"][data-page="${target}"]`);if(!link)continue;
   const n=unreadFor(target);let badge=$('.count',link);
   if(n){if(!badge){link.insertAdjacentHTML('beforeend',`<span class="count" aria-label="${n} unread">${n}</span>`);}else badge.textContent=String(n);}
   else badge?.remove();
  }
  const bell=$('[data-action="notifications"]');if(bell){let bellBadge=$('.count',bell);if(count){if(!bellBadge)bell.insertAdjacentHTML('beforeend',`<span class="count" aria-label="${count} unread notifications">${count>99?'99+':count}</span>`);else bellBadge.textContent=count>99?'99+':String(count);}else bellBadge?.remove();}
 }catch{}
}
async function renderPublic(token){
 let info;
 try{info=await api(`/api/public/${token}`);}catch(err){$('#app').innerHTML=`<main class="public-page"><div class="brand"><span class="brand-mark">h</span>haven</div>${empty('This link is unavailable',err.message)}</main>`;return;}
 const paid=info.balance_cents<=0;
 $('#app').innerHTML=`<main class="public-page"><header class="public-header"><div class="brand"><span class="brand-mark">h</span>haven</div><small>Secure payment-proof submission</small></header><section class="panel"><div class="eyebrow">${e(info.company)}</div><h1>${paid?'Thank you. Your balance is settled.':'Submit your payment receipt'}</h1><p class="subtitle">Hello ${e(info.tenant_name)} · ${e(info.property)}</p><div class="public-amount">${money(info.balance_cents)}</div><p class="subtitle">Outstanding · ${e(info.number)} · Due ${dateLabel(info.due_date)}</p><div class="notice">${icon('info')}<span>${e(info.payment_instructions||'Use the payment method agreed with your property manager.')}<br>Uploading a receipt does not complete a payment. Your manager will verify that the funds arrived.</span></div>${paid?'':`<form id="public-form"><div class="form-grid">${[amountField('amount','Amount paid (€)',(info.balance_cents/100).toFixed(2)),dayField('paid_on','Payment date'),selectField('method','Payment method',['Bank transfer','Mobile payment','Cash','Other']),['reference','Transaction / receipt reference','text',{required:false}],['file','Your receipt (PDF, PNG or JPEG)','file',{wide:true,hint:'Maximum 10 MB. Do not include identity documents or sensitive information unrelated to the payment.'}],['note','Anything else we should know?','textarea',{wide:true,required:false}]].map(field).join('')}</div><div class="form-error" role="alert"></div><button class="button primary" type="submit">${icon('upload')}Submit for verification</button></form>`}</section>${info.submissions.length?`<section class="panel"><h2>Your submissions</h2>${info.submissions.map(p=>`<div class="timeline-entry"><div class="actions"><strong>${money(p.amount_cents)}</strong>${badge(p.status)}</div><small>${dateLabel(p.paid_on)}</small>${p.review_note?`<p>${e(p.review_note)}</p>`:'<p class="subtitle">Your property manager will review the receipt.</p>'}</div>`).join('')}</section>`:''}<p class="public-note">Questions about this invoice? Contact your property manager.<br>Haven · Clear records. Better renting.</p></main>`;
 if(!paid)$('#public-form').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget;const b=$('button[type="submit"]',form);b.disabled=true;try{await api(`/api/public/${token}/proof`,{method:'POST',body:new FormData(form)});await renderPublic(token);toast('Receipt submitted. Your payment is awaiting verification.');}catch(err){$('.form-error',form).textContent=err.message;b.disabled=false;}});
}
async function boot(){
 if(['/tenant','/contractor','/owner'].includes(location.pathname)||location.pathname.startsWith('/activate/'))return;
 if(location.pathname.startsWith('/pay/')){await renderPublic(location.pathname.split('/').pop());return;}
 try{state.me=await api('/api/me');const stored=Number(sessionStorage.getItem('haven_company'));state.company=state.me.companies.some(c=>c.id===stored)?stored:[...state.me.companies].sort((a,b)=>a.id-b.id)[0]?.id;state.page=location.hash.slice(1)||'overview';await refresh();}catch(err){if(!state.me)renderLogin();else $('#app').innerHTML=empty('Unable to open workspace',err.message);}
}
boot();
setInterval(pollMessageBadge,20000);
